-- A multi-insert COPY whose buffer's flush finds a unique violation: the buffer's rows went
-- into the heap before their index entries (CopyMultiInsertBufferFlush's heap_multi_insert,
-- then each row's entries until the clash), so they stay as dead tuples and the next rows go
-- in after them; the indexes have entries for the rows before the clash only. Found at a
-- full buffer's flush (line 1000 of 1,100, the clash at line 500) and at the last one's.
CREATE TABLE a298_f (id int, a int NOT NULL, b text) WITH (autovacuum_enabled = off);
CREATE INDEX a298_f_a ON a298_f (a);
ALTER TABLE a298_f ADD PRIMARY KEY (id);
SELECT ctid, id FROM a298_f WHERE id IN (1, 10, 2001, 2010) ORDER BY id;
SELECT pg_relation_size('a298_f'), pg_relation_size('a298_f_pkey'), pg_relation_size('a298_f_a');
SELECT ctid, id FROM a298_f WHERE id > 4000 ORDER BY id;
SELECT pg_relation_size('a298_f'), pg_relation_size('a298_f_pkey'), pg_relation_size('a298_f_a');
SELECT count(*), sum(id) FROM a298_f;
SET enable_seqscan = off;
SELECT count(*), sum(a) FROM a298_f WHERE a >= 0;
SELECT count(*) FROM a298_f WHERE id > 0;
RESET enable_seqscan;
TRUNCATE a298_f;
SELECT ctid, id FROM a298_f ORDER BY id;
SELECT pg_relation_size('a298_f'), pg_relation_size('a298_f_pkey'), pg_relation_size('a298_f_a');
DROP TABLE a298_f;
